import math

def _find_player(entity):
    world = getattr(entity, "world", None)
    if world is not None and hasattr(world, "query"):
        for p in world.query("Health", "Stats"):
            if "player" in (getattr(p, "name", "") or "").lower():
                return p
        for p in world.query("Health"):
            if "player" in (getattr(p, "name", "") or "").lower():
                return p
    return None

